    'mcp_title' => 'KI-Agenten (MCP)',
    'mcp_note' => 'Claude Code, Codex, ChatGPT und andere KI-Agenten mit Ihrem CRM verbinden.',
    'mcp_why' => '<strong>Warum:</strong> MCP ermöglicht es KI-Agenten, Ihre Aufgaben, Projekte, Kunden und Chats über ein einziges Protokoll zu lesen und zu verwalten — mit denselben Zugriffsregeln wie die Weboberfläche.',
    'mcp_intro' => 'TropaTT enthält einen integrierten MCP-Server (Model Context Protocol) — dasselbe Protokoll, das von Claude Code, Codex, ChatGPT und anderen kompatiblen KI-Agenten verstanden wird.',
    'mcp_item1' => '<strong>567 MCP-Werkzeuge + 5 Ressourcen</strong> — Aufgaben, Projekte, Kunden, Kontakte, Chats, Kalender, Analytik, Wissensbasis.',
    'mcp_item2' => '<strong>Gleiche Daten und Regeln</strong> — jede Anfrage läuft über REST API und RBAC-Prüfungen, genau wie in der Weboberfläche.',
    'mcp_item3' => '<strong>Sicherheit</strong> — sensible Daten (Token, Passwort-Hashes, API-Schlüssel) werden gefiltert; Schreibvorgänge erfordern entsprechende Berechtigungen.',
    'mcp_item4' => '<strong>Endpunkt:</strong> POST /api/index.php?route=api/v1/mcp, Authentifizierung über Bearer-Token.',
    'mcp_docs_link' => 'Vollständige MCP-Dokumentation:',
    'usage_title' => 'Verwendungsszenarien',
    'usage_note' => 'Konkrete Szenarien für verschiedene Rollen und Branchen.',
    'usage_why' => '<strong>Warum:</strong> Diese Beispiele zeigen, wie TropaTT in realen Workflows genutzt wird — von der eingehenden Anfrage bis zur erledigten Aufgabe.',
    'usage_cycle_heading' => 'Vollständiger Kundenarbeitszyklus',
    'usage_step1' => '<strong>Erfassung</strong> — Idee, Kundenanfrage, Problem oder eingehender Lead.',
    'usage_step2' => '<strong>Analyse</strong> — eigenständig oder mit KI: Umfang, Risiken, Machbarkeit, Ansatz.',
    'usage_step3' => '<strong>Strukturierung</strong> — in Projekte, Aufgaben, Unteraufgaben, Checklisten, Verantwortliche, Fristen.',
    'usage_step4' => '<strong>Koordination</strong> — über Chat, Kommentare, @Erwähnungen, Benachrichtigungen.',
    'usage_step5' => '<strong>Ausführung</strong> — Aufgabenlisten, Kanban, Mein Tag, Meine Woche.',
    'usage_step6' => '<strong>Nachverfolgung</strong> — Gantt, Dashboards, Analytik, Auslastung, Risikosignale.',
    'usage_step7' => '<strong>Automatisierung</strong> — Workflow-Regeln, SLA, Webhooks, Freigabeketten.',
    'usage_examples_heading' => 'Konkrete Beispiele',
    'usage_ex1' => '<strong>Freelancer:</strong> Kundenanfrage → KI analysiert → Aufgabenplan → Mein Tag → Ausführung → Kundenchat → fertig.',
    'usage_ex2' => '<strong>Agentur:</strong> Kunden-Briefing → KI dekomponiert → Projekt + Meilensteine → Kanban → Gantt-Verfolgung → Kundenbericht → Analytik.',
    'usage_ex3' => '<strong>Dienstleister:</strong> Geschäftspartner → Projekt → Montageaufgaben → Gantt → Tagespläne → SLA-Überwachung → Abzeichnung.',
    'usage_ex4' => '<strong>B2B-Operationen:</strong> Unternehmen → Kontakte → Aufgaben + Freigaben → Erinnerungen → Webhook → Dashboard.',
    'tech_title' => 'Technologien & Kennzahlen',
    'tech_note' => 'Stack, Architektur und wichtige Projektmetriken.',
    'tech_why' => '<strong>Warum:</strong> Das Verständnis des Stacks hilft bei der Bewertung von Hosting-Anforderungen, Anpassungsmöglichkeiten und Systemskalierbarkeit.',
    'tech_stack_heading' => 'Technologiestack',
    'tech_stack1' => '<strong>Backend:</strong> PHP 8.1+, benutzerdefiniertes Mikrokernel. Null externe Abhängigkeiten. Kein Laravel/Symfony/Doctrine.',
    'tech_stack2' => '<strong>Datenbank:</strong> MySQL.',
    'tech_stack3' => '<strong>Frontend:</strong> PHP-gerendertes MPA + Bootstrap 5 + benutzerdefinierte Vanilla-JS-ES5+-Module. Kein React/Vue/Angular. Kein Bundler.',
    'tech_stack4' => '<strong>Architektur:</strong> API-first. Die Web-UI verwendet REST API für alle Daten. Null direkte DB-Aufrufe aus der Web-Schicht.',
    'tech_stack5' => '<strong>Sicherheit:</strong> Zweifache Authentifizierung (Cookie + CSRF für Web, Bearer für API). RBAC. SSRF-Schutz. Rate Limiting.',
    'tech_stack6' => '<strong>KI:</strong> Konfigurierbare Anbieter (OpenAI, Anthropic, DeepSeek, Google). Intent-Workflows. Preview-before-apply.',
